package check

// errorCodes are the names of kotlinc's diagnostics that the checker's
// errors are, by their messages' formats (Checker.errorf): what a
// language server reports as the error's code, and what tells it an error
// kotlinc would report too from one of kc's own limits. A format that
// isn't here, or that more than one of kotlinc's diagnostics share, has
// no code.
var errorCodes = map[string]string{
	"unresolved reference: %s":                                 "UNRESOLVED_REFERENCE",
	"unresolved import: %s":                                    "UNRESOLVED_IMPORT",
	"unresolved import: %s.*":                                  "UNRESOLVED_IMPORT",
	"unresolved label: %s":                                     "UNRESOLVED_LABEL",
	"conflicting declarations: %s":                             "REDECLARATION",
	"redeclaration: %s":                                        "REDECLARATION",
	"redeclaration: class %s":                                  "CLASSIFIER_REDECLARATION",
	"redeclaration: typealias %s":                              "CLASSIFIER_REDECLARATION",
	"conflicting overloads: %s":                                "CONFLICTING_OVERLOADS",
	"conflicting overloads: constructor%s":                     "CONFLICTING_OVERLOADS",
	"type mismatch: inferred type is %s but %s was expected":   "TYPE_MISMATCH",
	"type mismatch: inferred type is %s but Unit was expected": "TYPE_MISMATCH",
	"val cannot be reassigned":                                 "VAL_REASSIGNMENT",
	"variable expected":                                        "VARIABLE_EXPECTED",
	"variable '%s' must be initialized":                        "UNINITIALIZED_VARIABLE",
	"only safe (?.) or non-null asserted (!!.) calls are allowed on a nullable receiver of type %s": "UNSAFE_CALL",
	"cannot access '%s': it is %s":                                                                          "INVISIBLE_REFERENCE",
	"cannot access '%s': it is private in file":                                                             "INVISIBLE_REFERENCE",
	"none of the %d candidates for '%s' takes (%s)":                                                         "NONE_APPLICABLE",
	"cannot find a parameter with this name: %s":                                                            "NAMED_PARAMETER_NOT_FOUND",
	"the spread operator (*foo) can only be applied in a vararg position":                                   "NON_VARARG_SPREAD",
	"no context argument for '%s: %s' found":                                                                "NO_CONTEXT_ARGUMENT",
	"missing return statement in function '%s'":                                                             "NO_RETURN_IN_FUNCTION_WITH_BLOCK_BODY",
	"'%s' overrides nothing":                                                                                "NOTHING_TO_OVERRIDE",
	"'%s' in '%s' is final and cannot be overridden":                                                        "OVERRIDING_FINAL_MEMBER",
	"'%s' hides member of supertype '%s' and needs 'override' modifier":                                     "VIRTUAL_MEMBER_HIDDEN",
	"class '%s' must override '%s' because it inherits multiple implementations for it":                     "MANY_IMPL_MEMBER_NOT_IMPLEMENTED",
	"this type is final, so it cannot be inherited from":                                                    "FINAL_SUPERTYPE",
	"an interface cannot inherit from a class":                                                              "INTERFACE_WITH_SUPERCLASS",
	"an interface may not have a constructor":                                                               "CONSTRUCTOR_IN_INTERFACE",
	"constructors are not allowed for objects":                                                              "CONSTRUCTOR_IN_OBJECT",
	"constructor must be private in enum class":                                                             "NON_PRIVATE_CONSTRUCTOR_IN_ENUM",
	"property must be initialized or be abstract":                                                           "MUST_BE_INITIALIZED_OR_BE_ABSTRACT",
	"this property must have a type, be initialized, or have a getter with an expression body":              "PROPERTY_WITH_NO_TYPE_NO_INITIALIZER",
	"type argument is not within its bounds: type parameter '%s' must be subtype of '%s', but actual: '%s'": "UPPER_BOUND_VIOLATED",
	"no type arguments expected for class %s":                                                               "WRONG_NUMBER_OF_TYPE_ARGUMENTS",
	"no type arguments expected for '%s'":                                                                   "WRONG_NUMBER_OF_TYPE_ARGUMENTS",
	"cannot check for instance of erased type: %s":                                                          "CANNOT_CHECK_FOR_ERASED",
	"only type parameters of inline functions can be reified":                                               "REIFIED_TYPE_PARAMETER_NO_INLINE",
	"cannot use '%s' as reified type parameter":                                                             "TYPE_PARAMETER_AS_REIFIED",
	"cannot use '%s' as reified type parameter: use a class instead":                                        "TYPE_PARAMETER_AS_REIFIED",
	"illegal usage of inline-parameter '%s' in '%s': add 'noinline' modifier to the parameter declaration":  "USAGE_IS_NOT_INLINABLE",
	"the call of '%s' is a part of an inline call cycle":                                                    "INLINE_CALL_CYCLE",
	"cannot import on demand from object '%s'":                                                              "CANNOT_ALL_UNDER_IMPORT_FROM_SINGLETON",
	"this annotation is not repeatable":                                                                     "REPEATED_ANNOTATION",
	"this annotation is not applicable to target '%s'":                                                      "WRONG_ANNOTATION_TARGET",
	"only members in named objects and companion objects can be annotated with '@JvmStatic'":                "JVM_STATIC_NOT_IN_OBJECT_OR_COMPANION",
	"override member cannot be '@JvmStatic' in an object":                                                   "OVERRIDE_CANNOT_BE_STATIC",
	"accidental override: the following declarations have the same JVM signature (%s)":                      "ACCIDENTAL_OVERRIDE",
	"platform declaration clash: the following declarations have the same JVM signature (%s)":               "CONFLICTING_JVM_DECLARATIONS",
	"duplicate JVM class name '%s'":                                                                         "DUPLICATE_CLASS_NAMES",
	"value class cannot be recursive":                                                                       "VALUE_CLASS_CANNOT_BE_RECURSIVE",
}
